// ***************************************************************************
// Типы для CSS-модулей: side-effect импорты стилей (`import ".../x.css") —
// бандлятся без типов. Объявлено в отдельном скрипт-файле: TS не применяет
// wildcard-декларации из модульных .d.ts к side-effect импортам.
// ***************************************************************************

/** Модуль стилей (side-effect импорт, тип экспорта не нужен). */
declare module "*.css";
